-- hotels_tunisie.sql
-- 308 hôtels en Tunisie
-- Source de la liste des noms, villes et catégories : Firavia Travel
-- https://www.firaviatravel.tn/hotels?stars=%5B3%2C4%5D
-- Les coordonnées non vérifiées sont volontairement laissées à NULL.

BEGIN;

CREATE TABLE IF NOT EXISTS hotels (
    id SERIAL PRIMARY KEY,
    nom VARCHAR(255) NOT NULL,
    ville VARCHAR(100) NOT NULL,
    pays VARCHAR(100) NOT NULL DEFAULT 'Tunisie',
    categorie INTEGER,
    telephone VARCHAR(50),
    email VARCHAR(255),
    contact_reservation VARCHAR(255),
    adresse VARCHAR(500),
    observations TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_hotels_nom_ville UNIQUE (nom, ville)
);

CREATE INDEX IF NOT EXISTS ix_hotels_ville ON hotels (ville);
CREATE INDEX IF NOT EXISTS ix_hotels_categorie ON hotels (categorie);

-- Import des 308 hôtels.

COMMIT;

-- Total : 308 hôtels.